1	#ifndef GROKKING_KERNELS_SM90_SUPERGROK11_SM90_CUH_
2	#define GROKKING_KERNELS_SM90_SUPERGROK11_SM90_CUH_
3	// ============================================================================
4	// supergrok11_sm90.cuh — CANONICAL SuperGrok sm_90 device kernels for 'supergrok11'.
5	//
6	// This header is the SINGLE source of truth for the sm_90 device logic:
7	// templated __forceinline__ __device__ update/_vec4 functions, the __global__
8	// launcher kernels, every inline-PTX (asm-volatile) block VERBATIM, and (for
9	// muon/supergrok2) the CUTLASS Sm90 tensor-core collectives. It is a
10	// composition primitive for the future fused megakernel.
11	//
12	// The production TU csrc/backends/cuda/sm_90/launch_supergrok11.cu now #include's
13	// this header and keeps only the host launcher(s) the pybind layer calls.
14	// Migrated byte-for-byte from that .cu; verified compile-neutral via the
15	// preprocessor-equivalence gate (nvcc -E, modulo __FILE__).
16	// ============================================================================
17	// CUDA sm_90 launch glue for SuperGrok v1.1.
18	// Algorithm: csrc/algorithms/supergrok11.h
19	//
20	// Two-sweep cooperative pattern:
21	//   Sweep A: meta-net forward + cosine gate reduction
22	//   Sweep B: smart_grad mixing + Adam apply (uses gate from sweep A)
23	//
24	// The meta-net hidden width H is fixed at compile time. Defaults to 32
25	// (matches the canonical SharpnessMetaNet hidden_dim in
26	// grokking_optimizers/optimizers/supergrok11.py).
27	
28	#include <torch/extension.h>
29	#include <ATen/cuda/CUDAContext.h>
30	
31	#include "csrc/algorithms/supergrok11.h"
32	// ── Autotuner-consumable launch parameters (inlined; see compile.py) ──
33	#ifndef SG_TUNED_BLOCK_SIZE
34	#define SG_TUNED_BLOCK_SIZE 256
35	#endif
36	#ifndef SG_TUNED_VEC_WIDTH
37	#define SG_TUNED_VEC_WIDTH 4
38	#endif
39	#ifndef SG_TUNED_UNROLL
40	#define SG_TUNED_UNROLL 1
41	#endif
42	#ifndef SG_TUNED_ASYNC_DEPTH
43	#define SG_TUNED_ASYNC_DEPTH 2
44	#endif
45	#include "csrc/backends/cuda/sm_90/primitives.cuh"
46	#include "grokking_optimizers/kernels/sm_90/common_sm90.cuh"
47	
48	namespace sg { namespace sm90 {
49	
50	namespace prim = ::sg::sm90::primitives;
51	using ::sg::algorithms::sg11_phi_forward;
52	using ::sg::algorithms::sg11_sweep_a_step;
53	using ::sg::algorithms::sg11_sweep_b_step;
54	using ::sg::algorithms::sg11_adam_tail;
55	
56	constexpr int SG11_H = 32;
57	
58	// Minimum resident blocks/SM for the element-wise sweeps. Caps registers so
59	// occupancy stays high on the (memory-bound) Adam apply.
60	#ifndef SG_SUPERGROK11_MIN_BLOCKS
61	#define SG_SUPERGROK11_MIN_BLOCKS 4
62	#endif
63	
64	// Cooperatively stage the per-element meta-net phi weights into shared memory
65	// ONCE per block, then hand the shared pointers to the canonical
66	// sg11_phi_forward<H>. W1 is [H,2] (row-major, 2 inputs/hidden unit), b1/W2 are
67	// [H]. The same weights are read by every element this block processes; staging
68	// removes the per-element re-read from GLOBAL inside the H-wide forward loop. NO
69	// math/signature change — the fn still takes const float* (single-sourced in
70	// algorithms/supergrok11.h).
71	template <int H>
72	__device__ __forceinline__ void sg11_stage_phi_weights(
73	    const float* __restrict__ W1, const float* __restrict__ b1,
74	    const float* __restrict__ W2,
75	    float* sW1, float* sb1, float* sW2
76	) {
77	    for (int j = threadIdx.x; j < H * 2; j += blockDim.x) sW1[j] = W1[j];
78	    for (int j = threadIdx.x; j < H;     j += blockDim.x) { sb1[j] = b1[j]; sW2[j] = W2[j]; }
79	    __syncthreads();
80	}
81	
82	template <typename GradT>
83	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
84	sg11_sweep_a_kernel(
85	    float* mu_out, const GradT* grad, const float* sharpness, const float* momentum,
86	    const float* W1, const float* b1, const float* W2, float b2,
87	    float* gate_num_p, float* gate_den_g_p, float* gate_den_m_p,
88	    int64_t N
89	) {
90	    __shared__ float sW1[SG11_H * 2];
91	    __shared__ float sb1[SG11_H];
92	    __shared__ float sW2[SG11_H];
93	    sg11_stage_phi_weights<SG11_H>(W1, b1, W2, sW1, sb1, sW2);
94	
95	    float gn = 0.0f, gdg = 0.0f, gdm = 0.0f;
96	    const int64_t stride = prim::grid_stride();
97	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
98	        SG_SANITIZE_GRAD_INPLACE(grad, i);
99	        const float g = static_cast<float>(grad[i]);
100	        const float s = sharpness[i];
101	        const float mu_val = sg11_phi_forward<SG11_H>(g, s, sW1, sb1, sW2, b2);
102	        sg11_sweep_a_step(mu_out, grad, sharpness, momentum, mu_val, i,
103	                          gn, gdg, gdm);
104	    }
105	    float r1 = prim::block_reduce_sum_f32(gn);
106	    float r2 = prim::block_reduce_sum_f32(gdg);
107	    float r3 = prim::block_reduce_sum_f32(gdm);
108	    if (threadIdx.x == 0) {
109	        atomicAdd(gate_num_p, r1);
110	        atomicAdd(gate_den_g_p, r2);
111	        atomicAdd(gate_den_m_p, r3);
112	    }
113	}
114	
115	template <typename ParamT, typename GradT, int UNROLL>
116	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
117	sg11_sweep_b_kernel(
118	    ParamT* param, float* exp_avg, float* exp_avg_sq,
119	    const GradT* grad, const float* mu, float gate,
120	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
121	    float bc1, float bc2, int64_t N
122	) {
123	    const int64_t stride = prim::grid_stride() * UNROLL;
124	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
125	    for (int64_t base = base0; base < N; base += stride) {
126	        #pragma unroll
127	        for (int u = 0; u < UNROLL; ++u) {
128	            const int64_t i = base + u;
129	            if (i < N) {
130	                SG_SANITIZE_GRAD_INPLACE(grad, i);
131	                sg11_sweep_b_step(param, exp_avg, exp_avg_sq, grad, mu, gate,
132	                                  alpha, lr, beta1, beta2, eps, wd, bc1, bc2, i);
133	            }
134	        }
135	    }
136	}
137	
138	// FP32 vec4 sweep B: float4 traffic on param/state/grad/mu, canonical
139	// sg11_sweep_b_step CALLED 4× on the register lanes. Math is NOT re-typed here.
140	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
141	sg11_sweep_b_kernel_vec4_fp32(
142	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4,
143	    const float4* grad4, const float4* mu4, float gate,
144	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
145	    float bc1, float bc2, int64_t N4
146	) {
147	    const int64_t stride = prim::grid_stride();
148	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
149	        float4 p  = prim::ld_f32v4(param4 + i);
150	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
151	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
152	        float4 g  = prim::ldg_f32v4(grad4 + i);
153	        float4 mu = prim::ldg_f32v4(mu4 + i);
154	        ::grokking::sm90::sg_sanitize_grad4(g);
155	        #pragma unroll
156	        for (int u = 0; u < 4; ++u) {
157	            sg11_sweep_b_step(&p.x, &m.x, &v.x, &g.x, &mu.x, gate,
158	                              alpha, lr, beta1, beta2, eps, wd, bc1, bc2, u);
159	        }
160	        prim::st_f32v4(param4 + i, p);
161	        prim::st_f32v4(exp_avg4 + i, m);
162	        prim::st_f32v4(exp_avg_sq4 + i, v);
163	    }
164	}
165	
166	void launch_supergrok11_step(
167	    torch::Tensor& param,
168	    torch::Tensor& exp_avg,
169	    torch::Tensor& exp_avg_sq,
170	    torch::Tensor& mu_buf,
171	    const torch::Tensor& grad,
172	    const torch::Tensor& sharpness,
173	    const torch::Tensor& momentum,
174	    const torch::Tensor& phi_W1,
175	    const torch::Tensor& phi_b1,
176	    const torch::Tensor& phi_W2,
177	    float phi_b2,
178	    torch::Tensor& gate_partials,  // [3] {num, den_g, den_m}
179	    float alpha,
180	    float lr, float beta1, float beta2, float eps, float wd,
181	    float bc1, float bc2
182	) {
183	    const int64_t N = param.numel();
184	    if (N == 0) return;
185	
186	    auto stream = at::cuda::getCurrentCUDAStream().stream();
187	
188	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
189	    prim::L2PersistScope l2(stream,
190	        exp_avg.data_ptr(), exp_avg.nbytes(),
191	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
192	
193	    const int block = SG_TUNED_BLOCK_SIZE;
194	    const int grid = static_cast<int>(
195	        std::min<int64_t>(65535, (N + block - 1) / block));
196	
197	    gate_partials.zero_();
198	
199	    AT_DISPATCH_FLOATING_TYPES_AND2(
200	        at::ScalarType::Half, at::ScalarType::BFloat16,
201	        grad.scalar_type(), "sg11_sweep_a", [&] {
202	            sg11_sweep_a_kernel<scalar_t><<<grid, block, 0, stream>>>(
203	                mu_buf.data_ptr<float>(),
204	                grad.data_ptr<scalar_t>(),
205	                sharpness.data_ptr<float>(),
206	                momentum.data_ptr<float>(),
207	                phi_W1.data_ptr<float>(),
208	                phi_b1.data_ptr<float>(),
209	                phi_W2.data_ptr<float>(),
210	                phi_b2,
211	                gate_partials.data_ptr<float>(),
212	                gate_partials.data_ptr<float>() + 1,
213	                gate_partials.data_ptr<float>() + 2,
214	                N);
215	            SG_LAUNCH_CHECK(stream);
216	        });
217	
218	    // Host-side reduction of the 3 scalars and gate clamp.
219	    auto partials_cpu = gate_partials.to(torch::kCPU);
220	    float gn  = partials_cpu[0].item<float>();
221	    float gdg = partials_cpu[1].item<float>();
222	    float gdm = partials_cpu[2].item<float>();
223	    float denom = sqrtf(gdg * gdm + 1e-12f);
224	    float gate = (denom > 0.0f) ? (gn / denom) : 0.0f;
225	    gate = fminf(fmaxf(gate, 0.0f), 1.0f);
226	
227	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
228	                          grad.scalar_type() == torch::kFloat32;
229	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
230	        prim::is_vec4_alignable(param.data_ptr(), N) &&
231	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
232	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
233	        prim::is_vec4_alignable(grad.data_ptr(), N) &&
234	        prim::is_vec4_alignable(mu_buf.data_ptr(), N)) {
235	        const int64_t N4 = N / 4;
236	        const int grid4 = static_cast<int>(
237	            std::min<int64_t>(65535, (N4 + block - 1) / block));
238	        sg11_sweep_b_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
239	            reinterpret_cast<float4*>(param.data_ptr<float>()),
240	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
241	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
242	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
243	            reinterpret_cast<const float4*>(mu_buf.data_ptr<float>()),
244	            gate, alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N4);
245	        SG_LAUNCH_CHECK(stream);
246	        return;
247	    }
248	
249	    AT_DISPATCH_FLOATING_TYPES_AND2(
250	        at::ScalarType::Half, at::ScalarType::BFloat16,
251	        param.scalar_type(), "sg11_sweep_b", [&] {
252	            sg11_sweep_b_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
253	                <<<grid, block, 0, stream>>>(
254	                param.data_ptr<scalar_t>(),
255	                exp_avg.data_ptr<float>(),
256	                exp_avg_sq.data_ptr<float>(),
257	                grad.data_ptr<scalar_t>(),
258	                mu_buf.data_ptr<float>(),
259	                gate, alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N);
260	            SG_LAUNCH_CHECK(stream);
261	        });
262	}
263	
264	
265	// Meta-net forward: mu[i] = phi(grad[i], sharpness[i]); smart_grad = grad + alpha*mu
266	template <typename GradT>
267	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
268	sg11_mu_metanet_kernel(
269	    float* mu, const GradT* grad, const float* sharpness,
270	    float* smart_grad, float alpha,
271	    const float* W1, const float* b1, const float* W2, float b2_scalar,
272	    float rescale, int64_t N
273	) {
274	    __shared__ float sW1[SG11_H * 2];
275	    __shared__ float sb1[SG11_H];
276	    __shared__ float sW2[SG11_H];
277	    sg11_stage_phi_weights<SG11_H>(W1, b1, W2, sW1, sb1, sW2);
278	
279	    const int64_t stride = prim::grid_stride();
280	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
281	        SG_SANITIZE_GRAD_INPLACE(grad, i);
282	        float g = static_cast<float>(grad[i]);
283	        float s = sharpness[i];
284	        float phi = sg11_phi_forward<SG11_H>(g, s, sW1, sb1, sW2, b2_scalar) * rescale;
285	        mu[i] = phi;
286	        smart_grad[i] = g + alpha * phi;
287	    }
288	}
