75	template <typename GradT>
76	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK15_MIN_BLOCKS)
77	sg15_sweep_a_kernel(
78	    float* mu_out, const GradT* grad, const float* sharpness,
79	    const float* W1, const float* b1, const float* W2, float b2,
80	    float rescale, float* sharp_partial, int64_t N
81	) {
82	    __shared__ float sW1[SG15_H * 2];
83	    __shared__ float sb1[SG15_H];
84	    __shared__ float sW2[SG15_H];
85	    sg15_stage_phi_weights<SG15_H>(W1, b1, W2, sW1, sb1, sW2);
86	
87	    float sl = 0.0f;
88	    const int64_t stride = prim::grid_stride();
89	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
90	        SG_SANITIZE_GRAD_INPLACE(grad, i);
91	        const float g = static_cast<float>(grad[i]);
92	        const float s = sharpness[i];
93	        // Apply the trained rescale here (SharpnessMetaNet defines the
94	        // correction as rescale*MLP), mirroring SG11's mu_metanet kernel.
95	        // Previously rescale was dropped before this kernel, so mu_buf held the
96	        // bare MLP output (the H100 parity gate caught mu == MLP, not rescale*MLP).
97	        const float mu_val =
98	            rescale * sg15_phi_forward<SG15_H>(g, s, sW1, sb1, sW2, b2);
99	        sg15_sweep_a_step(mu_out, grad, mu_val, i, sl);
100	    }
101	    float r = prim::block_reduce_sum_f32(sl);
102	    if (threadIdx.x == 0) atomicAdd(sharp_partial, r);
103	}
