304	// Sharpness restore: param = backup, sharpness = (sam_grad - normal_grad)^2
305	template <typename ParamT>
306	__global__ void sg15_sharpness_restore_kernel(
307	    ParamT* param, float* sharpness, const ParamT* backup,
308	    const ParamT* sam_grad, const ParamT* normal_grad, int64_t N
309	) {
310	    const int64_t stride = prim::grid_stride();
311	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
312	        param[i] = backup[i];
313	        float diff = static_cast<float>(sam_grad[i]) -
314	                     static_cast<float>(normal_grad[i]);
315	        sharpness[i] = diff * diff;
316	    }
317	}
