1310	void supergrok11_fused_step(
1311	 std::vector<torch::Tensor>& params,
1312	 std::vector<torch::Tensor>& grads,
1313	 std::vector<torch::Tensor>& exp_avgs,
1314	 std::vector<torch::Tensor>& exp_avg_sqs,
1315	 std::vector<torch::Tensor>& mus,
1316	 std::vector<torch::Tensor>& sharpness_cache,
1317	 std::vector<int64_t>& steps,
1318	 std::vector<float>& layer_alphas,
1319	 std::vector<float>& layer_beta1s,
1320	 torch::Tensor W1, torch::Tensor b1,
1321	 torch::Tensor W2, torch::Tensor b2,
1322	 float rescale, int hidden_dim,
1323	 float beta2, float lr, float wd_eff, float eps,
1324	 float lamb, float ramp, float gate_temperature,
1325	 float grad_clip_norm
1326	) {
1327	 const size_t n_params = params.size();
1328	 check_params_grads(params, grads, "supergrok11_fused_step");
1329	 clip_grad_norms_device_side(grads, n_params, grad_clip_norm);
1330	
1331	 for (size_t i = 0; i < n_params; i++) {
1332	 if (!grads[i].defined() || grads[i].numel() == 0) continue;
1333	 // steps[i] is pre-incremented by the Python optimizer (SuperGrok11.step):
1334	 // pybind passes `steps` by value, so incrementing it here would NOT persist
1335	 // back to Python and would freeze bias-correction at t=1. Read it as-is.
1336	 float alpha = layer_alphas[i];
1337	 float beta1 = layer_beta1s[i];
1338	 float bc1 = 1.0f - std::pow(beta1, static_cast<float>(steps[i]));
1339	 float bc2 = 1.0f - std::pow(beta2, static_cast<float>(steps[i]));
1340	
1341	 // Canonical SuperGrok v1.1 mixing (csrc/algorithms/supergrok11.h:101,
1342	 // Pallas ref launch_supergrok11.py, oracle ref_sg11_step):
1343	 //   gate       = clamp(cosine(grad, mu), 0, 1)
1344	 //   smart_grad = grad + (1 - gate) * alpha * mu        (applied ONCE)
1345	 //   AdamW on smart_grad.
1346	 // The correction SHRINKS as grad/mu alignment (gate) grows — the polarity
1347	 // that lets a memorized solution HOLD. We reproduce this bit-exactly through
1348	 // the existing kernels by exact algebra, WITHOUT any kernel signature change:
1349	 //   * mu_metanet with alpha=0 writes mu = rescale*phi (mu is independent of
1350	 //     alpha, kernel line ~285) AND its smart_grad output = grad + 0*mu = grad.
1351	 //   * dispatch_cosine_gate(smart_grad==grad, mu) is therefore cosine(grad, mu).
1352	 //   * adam_decay computes g_eff = smart_grad + lamb_eff*mu; with
1353	 //     smart_grad==grad and lamb_eff=(1-gate)*alpha this equals exactly
1354	 //     grad + (1-gate)*alpha*mu, then the canonical Adam tail.
1355	 // `lamb`/`ramp` are NOT in the canonical formula (they were the buggy SECOND
1356	 // mu add `ramp*gate*lamb*mu`, whose coefficient GREW with the gate and
1357	 // destroyed the memorized solution); they are intentionally unused here.
1358	 (void)lamb; (void)ramp;
1359	 auto smart_grad = torch::empty_like(params[i]);
1360	 SG_DISPATCH_CALL(launch_sg11_mu_metanet,
1361	 mus[i], grads[i], sharpness_cache[i], smart_grad, /*alpha=*/0.0f,
1362	 W1, b1, W2, b2, rescale, hidden_dim);
1363	
1364	 float gate = dispatch_cosine_gate(smart_grad, mus[i], gate_temperature);
1365	 float lamb_eff = (1.0f - gate) * alpha;
1366	
1367	 SG_DISPATCH_CALL(launch_sg11_adam_decay,
1368	 params[i], exp_avgs[i], exp_avg_sqs[i], smart_grad, mus[i],
1369	 lamb_eff, beta1, beta2, lr, wd_eff, eps, bc1, bc2);
1370	 }
